<?php

declare(strict_types=1); require_once dirname(__DIR__).'/config.php'; admin_required(); $pdo=db();
$clubId=(int)($_GET['club_id']??0);$q=trim((string)($_GET['q']??''));
$where=[];$params=[]; if($clubId){$where[]='s.club_id=?';$params[]=$clubId;} if($q!==''){$where[]='(s.member_name LIKE ? OR s.phone LIKE ? OR s.bank_name LIKE ?)';$like='%'.$q.'%';array_push($params,$like,$like,$like);} $sql="SELECT s.*,c.name club_name FROM gift_submissions s JOIN gift_clubs c ON c.id=s.club_id".($where?' WHERE '.implode(' AND ',$where):'')." ORDER BY s.submitted_at DESC"; $st=$pdo->prepare($sql);$st->execute($params);$rows=$st->fetchAll();$clubs=$pdo->query("SELECT id,name FROM gift_clubs ORDER BY sort_order,id")->fetchAll();
?>
<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>제출내역</title><link rel="stylesheet" href="../assets/style.css"></head><body class="admin-body"><?php include __DIR__.'/_nav.php';?><main class="admin-wrap wide"><div class="page-head"><div><span class="eyebrow">관리</span><h1>제출내역</h1><p>동일 회원의 재제출은 최종 1건만 존재합니다.</p></div><a class="btn" href="export.php?club_id=<?=$clubId?>&q=<?=urlencode($q)?>">엑셀용 CSV 내려받기</a></div><section class="card"><form method="get" class="filter-bar"><select name="club_id"><option value="0">전체 동아리</option><?php foreach($clubs as $c):?><option value="<?=$c['id']?>" <?=$clubId==(int)$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select><input name="q" value="<?=e($q)?>" placeholder="성명·연락처·은행 검색"><button class="btn small" type="submit">검색</button><a class="btn small secondary" href="submissions.php">초기화</a><span class="count">총 <b><?=number_format(count($rows))?></b>건</span></form><div class="table-wrap"><table><thead><tr><th>동아리</th><th>성명</th><th>연락처</th><th>은행명</th><th>계좌번호</th><th>기타 코멘트</th><th>최종 제출일시</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['club_name'])?></td><td><b><?=e($r['member_name'])?></b></td><td><?=e($r['phone'])?></td><td><?=e($r['bank_name'])?></td><td class="account"><?=e($r['account_no'])?></td><td class="comment-cell"><?=e($r['comment'])?></td><td><?=e($r['submitted_at'])?></td></tr><?php endforeach;?><?php if(!$rows):?><tr><td colspan="7" class="empty">검색 결과가 없습니다.</td></tr><?php endif;?></tbody></table></div></section></main></body></html>
